-- ============================================================================
-- โครงสร้างฐานข้อมูลสำหรับโครงการ Ground Team (ระบบตอบโต้ระหว่างผู้ใช้กับแอดมิน)
-- Database: groundteam
-- Tables:
--   1. user         : รับข้อมูลของผู้ใช้และแอดมิน
--   2. job          : ข้อมูลกิจกรรมจิตอาสา (แอดมินเพิ่มและแก้ไขข้อมูลได้)
--   3. application  : รับข้อมูลที่ผู้ใช้สมัครกิจกรรม (แอดมินตอบรับได้)
--   4. contact      : รับข้อมูลในหน้า Contact ที่ผู้ใช้ส่งให้เรา
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. สร้างฐานข้อมูล groundteam
-- ----------------------------------------------------------------------------
CREATE DATABASE IF NOT EXISTS `groundteam` 
DEFAULT CHARACTER SET utf8mb4 
COLLATE utf8mb4_unicode_ci;

USE `groundteam`;

-- ----------------------------------------------------------------------------
-- 2. Table 1: user (รับข้อมูลของผู้ใช้)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` INT(11) NOT NULL AUTO_INCREMENT COMMENT 'รหัสลำดับสมาชิก (Primary Key)',
  `username` VARCHAR(50) NOT NULL COMMENT 'ชื่อผู้ใช้งานสำหรับเข้าสู่ระบบ',
  `password` VARCHAR(255) NOT NULL COMMENT 'รหัสผ่านสำหรับเข้าสู่ระบบ',
  `fullname` VARCHAR(150) NOT NULL COMMENT 'ชื่อ - สกุล',
  `phone` VARCHAR(20) NOT NULL COMMENT 'หมายเลขโทรศัพท์',
  `email` VARCHAR(100) NOT NULL COMMENT 'อีเมล',
  `province` VARCHAR(100) NOT NULL COMMENT 'จังหวัดที่อยู่ (รายการตัวเลือก)',
  `age` INT(3) NOT NULL COMMENT 'อายุ',
  `gender` ENUM('ชาย', 'หญิง', 'lgbtq+') NOT NULL DEFAULT 'ชาย' COMMENT 'เพศ (ชาย / หญิง / lgbtq+)',
  `role` VARCHAR(20) NOT NULL DEFAULT 'user' COMMENT 'สิทธิ์การใช้งาน (admin หรือ user)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันและเวลาที่ลงทะเบียน',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ตารางรับข้อมูลของผู้ใช้ Ground Team';

-- สำรอง tbground เพื่อความเข้ากันได้ย้อนหลัง
DROP TABLE IF EXISTS `tbground`;
CREATE TABLE `tbground` LIKE `user`;

-- ----------------------------------------------------------------------------
-- 3. Table 2: job (กิจกรรมจิตอาสา ให้แอดมินเพิ่มและแก้ไขข้อมูลได้)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `job`;
CREATE TABLE `job` (
  `id` INT(11) NOT NULL AUTO_INCREMENT COMMENT 'รหัสกิจกรรมจิตอาสา (Primary Key)',
  `title` VARCHAR(255) NOT NULL COMMENT 'ชื่อโครงการจิตอาสา',
  `description` TEXT NOT NULL COMMENT 'รายละเอียดกิจกรรม',
  `category` VARCHAR(100) NOT NULL DEFAULT 'recruiting' COMMENT 'หมวดหมู่ (เช่น recruiting, edu, nature, food, artificial, donate)',
  `event_date` VARCHAR(100) NOT NULL COMMENT 'วันที่จัดกิจกรรม (เช่น 25 ต.ค. พ.ศ.2569)',
  `event_time` VARCHAR(100) DEFAULT '09.00-16.00 น.' COMMENT 'เวลาจัดกิจกรรม',
  `location` VARCHAR(150) NOT NULL COMMENT 'สถานที่จัดกิจกรรม / จังหวัด',
  `hours` INT(5) NOT NULL DEFAULT 3 COMMENT 'จำนวนชั่วโมงจิตอาสาที่ได้รับรอง',
  `max_quota` INT(5) NOT NULL DEFAULT 30 COMMENT 'จำนวนรับสมัครทั้งหมด (คน)',
  `current_quota` INT(5) NOT NULL DEFAULT 0 COMMENT 'จำนวนที่สมัครแล้ว (คน)',
  `image_url` VARCHAR(255) DEFAULT 'assets/images/กระดาษทำมือ.jpeg' COMMENT 'พาธรูปภาพประกอบกิจกรรม',
  `status` ENUM('open', 'closed') NOT NULL DEFAULT 'open' COMMENT 'สถานะการเปิดรับสมัคร (open/closed)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่เพิ่มกิจกรรม',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'วันเวลาที่แก้ไขล่าสุด',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ตารางข้อมูลกิจกรรมจิตอาสา (Admin เพิ่มและแก้ไขได้)';

-- ----------------------------------------------------------------------------
-- 4. Table 3: application (รับข้อมูลที่ผู้ใช้สมัครกิจกรรม ให้แอดมินตอบรับได้)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `application`;
CREATE TABLE `application` (
  `id` INT(11) NOT NULL AUTO_INCREMENT COMMENT 'รหัสการสมัคร (Primary Key)',
  `user_id` INT(11) DEFAULT NULL COMMENT 'รหัสผู้ใช้งาน (FK user.id)',
  `job_id` INT(11) NOT NULL COMMENT 'รหัสกิจกรรมที่สมัคร (FK job.id)',
  `job_title` VARCHAR(255) NOT NULL COMMENT 'ชื่อโครงการจิตอาสาที่สมัคร',
  `fullname` VARCHAR(150) NOT NULL COMMENT 'ชื่อ - สกุลผู้สมัคร',
  `phone` VARCHAR(20) NOT NULL COMMENT 'หมายเลขโทรศัพท์',
  `email` VARCHAR(100) NOT NULL COMMENT 'อีเมล',
  `age` INT(3) NOT NULL COMMENT 'อายุผู้สมัคร',
  `skills` TEXT DEFAULT NULL COMMENT 'ทักษะความสามารถหรือประสบการณ์จิตอาสา',
  `status` ENUM('pending', 'approved', 'rejected') NOT NULL DEFAULT 'pending' COMMENT 'สถานะการตอบรับ (pending=รอตอบรับ, approved=ตอบรับแล้ว, rejected=ปฏิเสธ)',
  `admin_notes` TEXT DEFAULT NULL COMMENT 'ข้อความตอบกลับหรือหมายเหตุจากแอดมิน',
  `applied_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่สมัคร',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'วันเวลาที่แอดมินตอบรับหรืออัปเดต',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_job_id` (`job_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ตารางรับข้อมูลการสมัครกิจกรรม (Admin ตอบรับได้)';

-- ----------------------------------------------------------------------------
-- 5. Table 4: contact (รับข้อมูลในหน้า Contact ที่ผู้ใช้ส่งให้เรา)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `contact`;
CREATE TABLE `contact` (
  `id` INT(11) NOT NULL AUTO_INCREMENT COMMENT 'รหัสข้อความติดต่อ (Primary Key)',
  `name` VARCHAR(150) NOT NULL COMMENT 'ชื่อ - นามสกุลผู้ส่งข้อความ',
  `email` VARCHAR(100) NOT NULL COMMENT 'อีเมลสำหรับติดต่อกลับ',
  `phone` VARCHAR(20) NOT NULL COMMENT 'หมายเลขโทรศัพท์',
  `subject` VARCHAR(150) NOT NULL COMMENT 'หัวข้อที่ติดต่อ',
  `message` TEXT NOT NULL COMMENT 'ข้อความรายละเอียดที่ส่งถึงเรา',
  `status` ENUM('unread', 'read', 'replied') NOT NULL DEFAULT 'unread' COMMENT 'สถานะข้อความ (unread=ยังไม่อ่าน, read=อ่านแล้ว, replied=ตอบกลับแล้ว)',
  `reply_message` TEXT DEFAULT NULL COMMENT 'ข้อความตอบกลับหรือบันทึกของแอดมิน',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่ส่งข้อความ',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ตารางรับข้อมูลในหน้า Contact ที่ผู้ใช้ส่งให้เรา';

-- ============================================================================
-- 6. ข้อมูลเริ่มต้นสำหรับการทดสอบระบบ (Seed Data)
