-- ข้อมูล Table 2: job (18 โครงการจิตอาสาเริ่มต้น)
INSERT INTO `job` (`id`, `title`, `description`, `category`, `event_date`, `event_time`, `location`, `hours`, `max_quota`, `current_quota`, `image_url`, `status`) VALUES
(1, 'จิตอาสาทำสมุดทำมือจากกระดาษรีไซเคิลให้น้อง ๆ ด้อยโอกาส', 'ร่วมทำสมุดจากกระดาษเหลือใช้ ที่นำกลับมารีไซเคิลให้เป็นสมุดที่พร้อมใช้งานอีกครั้ง เพื่อนำไปบริจาคต่อให้กับน้อง ๆ ที่ขาดแคลนทุนทรัพย์ตามถิ่นทุรกันดาร', 'recruiting,edu', '25 ต.ค. พ.ศ.2569', '13.00-17.00 น.', 'จ.มหาสารคาม', 4, 50, 15, 'assets/images/กระดาษทำมือ.jpeg', 'open'),
(2, 'โครงการมื้ออาหารกลางวัน เพื่อเด็ก', 'จิตอาสาไปร่วมกันช่วยทำมื้ออาหารกลางวันให้แก่เด็ก ๆ เพื่อช่วยในเรื่องของโภชนาการของน้อง ๆ ในวัยเรียน และช่วยลดค่าใช้จ่ายในครัวเรือน', 'recruiting,food', '28 ต.ค. พ.ศ.2569', '10.00-15.00 น.', 'จ.นครพนม', 5, 20, 5, 'assets/images/แจกอาหารกลางวันเด็ก.jpg', 'open'),
(3, 'จิตอาสาจัดชุดสุขอนามัยแบ่งปันให้ผู้ยากไร้', 'ร่วมแพ็คและจัดเตรียมสบู่ ยาสระผม แปรงสีฟัน ผ้าเช็ดตัว และของใช้จำเป็น เพื่อแจกจ่ายให้แก่ผู้ยากไร้และผู้ประสบภัยในพื้นที่ห่างไกล', 'recruiting,donate', '5 พ.ย. พ.ศ.2569', '09.00-12.00 น.', 'จ.บุรีรัมย์', 3, 40, 18, 'assets/images/จัดชุดสุขอนามัยแบ่งปันให้ผู้ยากไร้.PNG', 'open'),
(4, 'จิตอาสาทำถุงผ้าจากเสื้อผ้าเก่าเพื่อผู้ขาดแคลน', 'นำเสื้อผ้าที่ไม่ใช้แล้วมาตัดเย็บเป็นถุงผ้าสารพัดประโยชน์ ลดขยะสิ่งทอ และส่งมอบถุงผ้าให้ศูนย์การแพทย์ชุมชนใส่ยากลับบ้าน', 'recruiting,artificial', '12 พ.ย. พ.ศ.2569', '13.00-16.30 น.', 'จ.มหาสารคาม', 3, 25, 12, 'assets/images/ทำถุงผ้าจากเสื้อผ้าเก่า.PNG', 'open'),
(5, 'จิตอาสาจัดถุงยังชีพแบ่งปันให้ครอบครัวผู้ยากไร้', 'ร่วมบรรจุข้าวสาร อาหารแห้ง และยารักษาโรคลงในถุงยังชีพ เพื่อส่งมอบให้กับครอบครัวผู้มีรายได้น้อยและผู้ป่วยติดเตียง', 'recruiting,donate', '18 พ.ย. พ.ศ.2569', '08.30-14.00 น.', 'จ.นครราชสีมา', 5, 30, 20, 'assets/images/จัดถุงยังชีพ.jpg', 'open'),
(6, 'จิตอาสาพี่สอนน้อง อ่านนิทานสร้างจินตนาการ', 'ร่วมจัดกิจกรรมอ่านนิทาน สอนการบ้าน และทำกิจกรรมศิลปะร่วมกับเด็ก ๆ เพื่อส่งเสริมทักษะการอ่านและความคิดสร้างสรรค์', 'recruiting,edu', '21 พ.ย. พ.ศ.2569', '09.00-12.00 น.', 'จ.กาฬสินธุ์', 3, 20, 7, 'assets/images/พี่สอนน้อง.jpg', 'open'),
(7, 'จิตอาสาปลูกต้นไม้เพิ่มพื้นที่สีเขียวให้ชุมชน', 'ลงพื้นที่ปลูกต้นไม้ยืนต้นและไม้ดอก เพื่อฟื้นฟูธรรมชาติ เพิ่มร่มเงา ลดก๊าซคาร์บอนไดออกไซด์ และสร้างสภาพแวดล้อมที่น่าอยู่', 'recruiting,nature', '24 พ.ย. พ.ศ.2569', '08.00-12.00 น.', 'จ.ร้อยเอ็ด', 4, 60, 42, 'assets/images/ปลูกต้นไม้.jpg', 'open'),
(8, 'จิตอาสาเก็บขยะและทำความสะอาดชุมชน', 'ร่วมกันเก็บขยะและทำความสะอาดพื้นที่สาธารณะ ปลูกจิตสำนึกเรื่องการรักษาสิ่งแวดล้อม และสร้างสุขอนามัยที่ดีให้ชุมชน', 'recruiting,nature', '26 พ.ย. พ.ศ.2569', '08.30-11.30 น.', 'จ.มหาสารคาม', 3, 35, 28, 'assets/images/เก็บขยะชุมชน.jpg', 'open'),
(9, 'จิตอาสาคัดแยกขยะสร้างประโยชน์เพื่อสังคม', 'ร่วมคัดแยกขวดพลาสติก กระดาษ และวัสดุรีไซเคิล เพื่อนำส่งเข้าสู่กระบวนการรีไซเคิลอย่างเหมาะสม พร้อมให้ความรู้เรื่องการจัดการขยะ', 'recruiting,nature', '27 พ.ย. พ.ศ.2569', '09.00-15.00 น.', 'จ.ขอนแก่น', 6, 25, 14, 'assets/images/คัดแยกขยะ.jpg', 'open'),
(10, 'จิตอาสาจัดชุดอุปกรณ์การเรียนเพื่อน้อง', 'จัดเตรียมสมุด ดินสอ สี และเครื่องเขียน ใส่กระเป๋าอุปกรณ์การเรียน เพื่อส่งมอบให้โรงเรียนในพื้นที่ชนบท', 'recruiting,edu', '28 พ.ย. พ.ศ.2569', '13.00-16.00 น.', 'จ.ขอนแก่น', 3, 40, 19, 'assets/images/จัดชุดอุปกรณ์การเรียน.avif', 'open'),
(11, 'จิตอาสาประดิษฐ์ที่คั่นหนังสือจากกระดาษเหลือใช้', 'นำเศษกระดาษ ลัง และวัสดุเหลือใช้มาประดิษฐ์และออกแบบเป็นที่คั่นหนังสือน่ารัก ๆ เพื่อส่งมอบให้ห้องสมุดชุมชนและโรงเรียนที่ขาดแคลน', 'recruiting,artificial', '29 พ.ย. พ.ศ.2569', '13.00-16.00 น.', 'จ.มหาสารคาม', 3, 30, 15, 'assets/images/ที่คั่นหนังสือ.jpg', 'open'),
(12, 'กิจกรรมอาสาสอนผู้สูงอายุใช้สมาร์ทโฟน', 'แนะนำวิธีการใช้งานแอปพลิเคชันพื้นฐาน การโทรวิดีโอคอล การสแกนจ่ายเงิน และการรู้เท่าทันมิจฉาชีพทางออนไลน์ให้ผู้สูงอายุ', 'recruiting,edu', '1 ธ.ค. พ.ศ.2569', '09.00-12.00 น.', 'จ.นครราชสีมา', 3, 20, 9, 'assets/images/สอนผู้สูงอายุใช้สมาร์ทโฟน.jpg', 'open'),
(13, 'จิตอาสาประดิษฐ์งานศิลปะส่งกำลังใจให้ผู้ป่วย', 'ร่วมประดิษฐ์การ์ดอวยพร ดอกไม้กระดาษ และงานศิลปะแฮนด์เมด เพื่อส่งมอบกำลังใจให้แก่ผู้ป่วยพักฟื้นระยะยาวในโรงพยาบาล', 'recruiting,artificial', '3 ธ.ค. พ.ศ.2569', '13.00-16.30 น.', 'จ.ขอนแก่น', 3, 25, 11, 'assets/images/ทำการ์ด.jpg', 'open'),
(14, 'โครงการจิตอาสาวาดภาพการ์ตูนนิทานช่วยพัฒนาเยาวชน', 'วาดภาพการ์ตูนนิทานและระบายสีบนกำแพงโรงเรียน เพื่อสร้างบรรยากาศการเรียนรู้ที่สดใสและเสริมสร้างจินตนาการแก่น้อง ๆ', 'recruiting,edu', '5 ธ.ค. พ.ศ.2569', '09.00-15.00 น.', 'จ.นครพนม', 5, 20, 8, 'assets/images/วาดภาพการ์ตูน.jpg', 'open'),
(15, 'โครงการจิตอาสาเก็บขยะชายหาดจังหวัดชลบุรี', 'ร่วมแรงร่วมใจเก็บขยะบริเวณแนวชายหาด ลดปริมาณขยะพลาสติกไหลลงสู่ทะเล และปกป้องสัตว์ทะเลหายาก', 'recruiting,nature', '8 ธ.ค. พ.ศ.2569', '08.00-12.00 น.', 'จ.ชลบุรี', 4, 50, 33, 'assets/images/เก็บขยะชายหาด.jpg', 'open'),
(16, 'โครงการมื้ออาหารกลางวันเพื่อเด็กด้อยโอกาส', 'ทำอาหารกลางวันที่มีคุณค่าทางโภชนาการครบถ้วน และแจกจ่ายขนมของว่างให้น้อง ๆ ในศูนย์ดูแลเด็กด้อยโอกาส', 'recruiting,food', '11 ธ.ค. พ.ศ.2569', '10.00-14.30 น.', 'จ.อุบลราชธานี', 4, 25, 17, 'assets/images/อาหารกลางวันเด็กด้อยโอกาส.jpg', 'open'),
(17, 'โครงการจิตอาสาแบ่งปันเพื่อการเปลี่ยนแปลง', 'รวบรวมและคัดแยกสิ่งของบริจาค เสื้อผ้า อุปกรณ์กีฬา และของเล่น เพื่อกระจายให้แก่ชุมชนที่ต้องการความช่วยเหลือ', 'recruiting,donate', '15 ธ.ค. พ.ศ.2569', '09.00-13.00 น.', 'จ.อุดรธานี', 4, 30, 16, 'assets/images/แบ่งปันเพื่อการเปลี่ยนแปลง.jpg', 'open'),
(18, 'โครงการจิตอาสาคัดแยกหนังสือส่งต่อให้น้องในพื้นที่ห่างไกล', 'คัดแยก ซ่อมแซม และบรรจุกล่องหนังสือวรรณกรรม หนังสือนิทาน และตำราเรียน เพื่อจัดส่งไปยังห้องสมุดโรงเรียนบนดอย', 'recruiting,donate', '19 ธ.ค. พ.ศ.2569', '09.00-16.00 น.', 'จ.เชียงใหม่', 6, 20, 10, 'assets/images/ส่งหนังสือให้เด็กในพื้นที่ห่างไกล.jpg', 'open');

-- ข้อมูล Table 3: application (ตัวอย่างการสมัครและการตอบรับของแอดมิน)
INSERT INTO `application` (`id`, `user_id`, `job_id`, `job_title`, `fullname`, `phone`, `email`, `age`, `skills`, `status`, `admin_notes`, `applied_at`) VALUES
(1, 2, 1, 'จิตอาสาทำสมุดทำมือจากกระดาษรีไซเคิลให้น้อง ๆ ด้อยโอกาส', 'สมชาย ใจดี', '0812345678', 'somchai@example.com', 24, 'เคยทำงานประดิษฐ์ มีความชำนาญการพับกระดาษ', 'approved', 'ยินดีต้อนรับครับ กรุณาเตรียมตัวมาร่วมกิจกรรมตามวันเวลาที่กำหนด', '2026-10-12 10:30:00'),
(2, 3, 2, 'โครงการมื้ออาหารกลางวัน เพื่อเด็ก', 'ณิชา วงศ์สวรรค์', '0898765432', 'nicha@example.com', 21, 'ช่วยทำครัว จัดเตรียมวัตถุดิบอาหารได้คล่อง', 'approved', 'ตอบรับเข้าร่วมโครงการเรียบร้อย มีประกันอุบัติเหตุและอาหารกลางวันดูแล', '2026-10-13 14:15:00'),
(3, 4, 7, 'จิตอาสาปลูกต้นไม้เพิ่มพื้นที่สีเขียวให้ชุมชน', 'อเล็กซ์ รัตนโชติ', '0865554321', 'alex@example.com', 26, 'ถ่ายภาพนิ่งและวิดีโอสำหรับโปรโมทกิจกรรมได้', 'pending', NULL, '2026-10-14 09:00:00');

-- ข้อมูล Table 4: contact (ตัวอย่างข้อความติดต่อจากผู้ใช้)
INSERT INTO `contact` (`id`, `name`, `email`, `phone`, `subject`, `message`, `status`, `reply_message`, `created_at`) VALUES
(1, 'กนกวรรณ รัตนโชติ', 'kanokwan@example.com', '0823456789', 'สอบถามรายละเอียดกิจกรรมจิตอาสา', 'อยากสอบถามว่ากิจกรรมปลูกป่าที่ จ.ร้อยเอ็ด มีรถตู้รับส่งจากตัวเมืองไหมคะ?', 'read', 'ประสานงานแจ้งจุดขึ้นรถตู้เรียบร้อยแล้ว', '2026-10-14 11:20:00'),
(2, 'กิตติศักดิ์ ทองทา', 'kittisak@example.com', '0891112233', 'เสนอโครงการ / ชวนเป็นเครือข่ายพันธมิตร', 'ทางกลุ่มเยาวชนอาสาขอนแก่น สนใจร่วมจัดกิจกรรมคัดแยกขยะพลาสติกในสถานศึกษา อยากนัดหารือความร่วมมือครับ', 'unread', NULL, '2026-10-15 08:45:00');

-- ข้อมูล Table 2: job (18 โครงการจิตอาสาเริ่มต้น)
INSERT INTO `job` (`id`, `title`, `description`, `category`, `event_date`, `event_time`, `location`, `hours`, `max_quota`, `current_quota`, `image_url`, `status`) VALUES
(1, 'จิตอาสาทำสมุดทำมือจากกระดาษรีไซเคิลให้น้อง ๆ ด้อยโอกาส', 'ร่วมทำสมุดจากกระดาษเหลือใช้ ที่นำกลับมารีไซเคิลให้เป็นสมุดที่พร้อมใช้งานอีกครั้ง เพื่อนำไปบริจาคต่อให้กับน้อง ๆ ที่ขาดแคลนทุนทรัพย์ตามถิ่นทุรกันดาร', 'recruiting,edu', '25 ต.ค. พ.ศ.2569', '13.00-17.00 น.', 'จ.มหาสารคาม', 4, 50, 15, 'assets/images/กระดาษทำมือ.jpeg', 'open'),
(2, 'โครงการมื้ออาหารกลางวัน เพื่อเด็ก', 'จิตอาสาไปร่วมกันช่วยทำมื้ออาหารกลางวันให้แก่เด็ก ๆ เพื่อช่วยในเรื่องของโภชนาการของน้อง ๆ ในวัยเรียน และช่วยลดค่าใช้จ่ายในครัวเรือน', 'recruiting,food', '28 ต.ค. พ.ศ.2569', '10.00-15.00 น.', 'จ.นครพนม', 5, 20, 5, 'assets/images/แจกอาหารกลางวันเด็ก.jpg', 'open'),
(3, 'จิตอาสาจัดชุดสุขอนามัยแบ่งปันให้ผู้ยากไร้', 'ร่วมแพ็คและจัดเตรียมสบู่ ยาสระผม แปรงสีฟัน ผ้าเช็ดตัว และของใช้จำเป็น เพื่อแจกจ่ายให้แก่ผู้ยากไร้และผู้ประสบภัยในพื้นที่ห่างไกล', 'recruiting,donate', '5 พ.ย. พ.ศ.2569', '09.00-12.00 น.', 'จ.บุรีรัมย์', 3, 40, 18, 'assets/images/จัดชุดสุขอนามัยแบ่งปันให้ผู้ยากไร้.PNG', 'open'),
(4, 'จิตอาสาทำถุงผ้าจากเสื้อผ้าเก่าเพื่อผู้ขาดแคลน', 'นำเสื้อผ้าที่ไม่ใช้แล้วมาตัดเย็บเป็นถุงผ้าสารพัดประโยชน์ ลดขยะสิ่งทอ และส่งมอบถุงผ้าให้ศูนย์การแพทย์ชุมชนใส่ยากลับบ้าน', 'recruiting,artificial', '12 พ.ย. พ.ศ.2569', '13.00-16.30 น.', 'จ.มหาสารคาม', 3, 25, 12, 'assets/images/ทำถุงผ้าจากเสื้อผ้าเก่า.PNG', 'open'),
(5, 'จิตอาสาจัดถุงยังชีพแบ่งปันให้ครอบครัวผู้ยากไร้', 'ร่วมบรรจุข้าวสาร อาหารแห้ง และยารักษาโรคลงในถุงยังชีพ เพื่อส่งมอบให้กับครอบครัวผู้มีรายได้น้อยและผู้ป่วยติดเตียง', 'recruiting,donate', '18 พ.ย. พ.ศ.2569', '08.30-14.00 น.', 'จ.นครราชสีมา', 5, 30, 20, 'assets/images/จัดถุงยังชีพ.jpg', 'open'),
(6, 'จิตอาสาพี่สอนน้อง อ่านนิทานสร้างจินตนาการ', 'ร่วมจัดกิจกรรมอ่านนิทาน สอนการบ้าน และทำกิจกรรมศิลปะร่วมกับเด็ก ๆ เพื่อส่งเสริมทักษะการอ่านและความคิดสร้างสรรค์', 'recruiting,edu', '21 พ.ย. พ.ศ.2569', '09.00-12.00 น.', 'จ.กาฬสินธุ์', 3, 20, 7, 'assets/images/พี่สอนน้อง.jpg', 'open'),
(7, 'จิตอาสาปลูกต้นไม้เพิ่มพื้นที่สีเขียวให้ชุมชน', 'ลงพื้นที่ปลูกต้นไม้ยืนต้นและไม้ดอก เพื่อฟื้นฟูธรรมชาติ เพิ่มร่มเงา ลดก๊าซคาร์บอนไดออกไซด์ และสร้างสภาพแวดล้อมที่น่าอยู่', 'recruiting,nature', '24 พ.ย. พ.ศ.2569', '08.00-12.00 น.', 'จ.ร้อยเอ็ด', 4, 60, 42, 'assets/images/ปลูกต้นไม้.jpg', 'open'),
(8, 'จิตอาสาเก็บขยะและทำความสะอาดชุมชน', 'ร่วมกันเก็บขยะและทำความสะอาดพื้นที่สาธารณะ ปลูกจิตสำนึกเรื่องการรักษาสิ่งแวดล้อม และสร้างสุขอนามัยที่ดีให้ชุมชน', 'recruiting,nature', '26 พ.ย. พ.ศ.2569', '08.30-11.30 น.', 'จ.มหาสารคาม', 3, 35, 28, 'assets/images/เก็บขยะชุมชน.jpg', 'open'),
(9, 'จิตอาสาคัดแยกขยะสร้างประโยชน์เพื่อสังคม', 'ร่วมคัดแยกขวดพลาสติก กระดาษ และวัสดุรีไซเคิล เพื่อนำส่งเข้าสู่กระบวนการรีไซเคิลอย่างเหมาะสม พร้อมให้ความรู้เรื่องการจัดการขยะ', 'recruiting,nature', '27 พ.ย. พ.ศ.2569', '09.00-15.00 น.', 'จ.ขอนแก่น', 6, 25, 14, 'assets/images/คัดแยกขยะ.jpg', 'open'),
(10, 'จิตอาสาจัดชุดอุปกรณ์การเรียนเพื่อน้อง', 'จัดเตรียมสมุด ดินสอ สี และเครื่องเขียน ใส่กระเป๋าอุปกรณ์การเรียน เพื่อส่งมอบให้โรงเรียนในพื้นที่ชนบท', 'recruiting,edu', '28 พ.ย. พ.ศ.2569', '13.00-16.00 น.', 'จ.ขอนแก่น', 3, 40, 19, 'assets/images/จัดชุดอุปกรณ์การเรียน.avif', 'open'),
(11, 'จิตอาสาประดิษฐ์ที่คั่นหนังสือจากกระดาษเหลือใช้', 'นำเศษกระดาษ ลัง และวัสดุเหลือใช้มาประดิษฐ์และออกแบบเป็นที่คั่นหนังสือน่ารัก ๆ เพื่อส่งมอบให้ห้องสมุดชุมชนและโรงเรียนที่ขาดแคลน', 'recruiting,artificial', '29 พ.ย. พ.ศ.2569', '13.00-16.00 น.', 'จ.มหาสารคาม', 3, 30, 15, 'assets/images/ที่คั่นหนังสือ.jpg', 'open'),
(12, 'กิจกรรมอาสาสอนผู้สูงอายุใช้สมาร์ทโฟน', 'แนะนำวิธีการใช้งานแอปพลิเคชันพื้นฐาน การโทรวิดีโอคอล การสแกนจ่ายเงิน และการรู้เท่าทันมิจฉาชีพทางออนไลน์ให้ผู้สูงอายุ', 'recruiting,edu', '1 ธ.ค. พ.ศ.2569', '09.00-12.00 น.', 'จ.นครราชสีมา', 3, 20, 9, 'assets/images/สอนผู้สูงอายุใช้สมาร์ทโฟน.jpg', 'open'),
(13, 'จิตอาสาประดิษฐ์งานศิลปะส่งกำลังใจให้ผู้ป่วย', 'ร่วมประดิษฐ์การ์ดอวยพร ดอกไม้กระดาษ และงานศิลปะแฮนด์เมด เพื่อส่งมอบกำลังใจให้แก่ผู้ป่วยพักฟื้นระยะยาวในโรงพยาบาล', 'recruiting,artificial', '3 ธ.ค. พ.ศ.2569', '13.00-16.30 น.', 'จ.ขอนแก่น', 3, 25, 11, 'assets/images/ทำการ์ด.jpg', 'open'),
(14, 'โครงการจิตอาสาวาดภาพการ์ตูนนิทานช่วยพัฒนาเยาวชน', 'วาดภาพการ์ตูนนิทานและระบายสีบนกำแพงโรงเรียน เพื่อสร้างบรรยากาศการเรียนรู้ที่สดใสและเสริมสร้างจินตนาการแก่น้อง ๆ', 'recruiting,edu', '5 ธ.ค. พ.ศ.2569', '09.00-15.00 น.', 'จ.นครพนม', 5, 20, 8, 'assets/images/วาดภาพการ์ตูน.jpg', 'open'),
(15, 'โครงการจิตอาสาเก็บขยะชายหาดจังหวัดชลบุรี', 'ร่วมแรงร่วมใจเก็บขยะบริเวณแนวชายหาด ลดปริมาณขยะพลาสติกไหลลงสู่ทะเล และปกป้องสัตว์ทะเลหายาก', 'recruiting,nature', '8 ธ.ค. พ.ศ.2569', '08.00-12.00 น.', 'จ.ชลบุรี', 4, 50, 33, 'assets/images/เก็บขยะชายหาด.jpg', 'open'),
(16, 'โครงการมื้ออาหารกลางวันเพื่อเด็กด้อยโอกาส', 'ทำอาหารกลางวันที่มีคุณค่าทางโภชนาการครบถ้วน และแจกจ่ายขนมของว่างให้น้อง ๆ ในศูนย์ดูแลเด็กด้อยโอกาส', 'recruiting,food', '11 ธ.ค. พ.ศ.2569', '10.00-14.30 น.', 'จ.อุบลราชธานี', 4, 25, 17, 'assets/images/อาหารกลางวันเด็กด้อยโอกาส.jpg', 'open'),
(17, 'โครงการจิตอาสาแบ่งปันเพื่อการเปลี่ยนแปลง', 'รวบรวมและคัดแยกสิ่งของบริจาค เสื้อผ้า อุปกรณ์กีฬา และของเล่น เพื่อกระจายให้แก่ชุมชนที่ต้องการความช่วยเหลือ', 'recruiting,donate', '15 ธ.ค. พ.ศ.2569', '09.00-13.00 น.', 'จ.อุดรธานี', 4, 30, 16, 'assets/images/แบ่งปันเพื่อการเปลี่ยนแปลง.jpg', 'open'),
(18, 'โครงการจิตอาสาคัดแยกหนังสือส่งต่อให้น้องในพื้นที่ห่างไกล', 'คัดแยก ซ่อมแซม และบรรจุกล่องหนังสือวรรณกรรม หนังสือนิทาน และตำราเรียน เพื่อจัดส่งไปยังห้องสมุดโรงเรียนบนดอย', 'recruiting,donate', '19 ธ.ค. พ.ศ.2569', '09.00-16.00 น.', 'จ.เชียงใหม่', 6, 20, 10, 'assets/images/ส่งหนังสือให้เด็กในพื้นที่ห่างไกล.jpg', 'open');

-- ข้อมูล Table 3: application (ตัวอย่างการสมัครและการตอบรับของแอดมิน)
